from collections import deque
class Solution:
    def minimumSeconds(self, land: List[List[str]]) -> int:
        n, m = len(land), len(land[0])
        INF = float('inf')
        flood = [[INF]*m for _ in range(n)]
        q = deque()
        si = sj = di = dj = 0
        for i in range(n):
            for j in range(m):
                if land[i][j] == '*':
                    flood[i][j] = 0; q.append((i, j))
                elif land[i][j] == 'S': si, sj = i, j
                elif land[i][j] == 'D': di, dj = i, j
        while q:
            i, j = q.popleft()
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                x, y = i+dx, j+dy
                if 0 <= x < n and 0 <= y < m and land[x][y] == '.' and flood[x][y] == INF:
                    flood[x][y] = flood[i][j] + 1
                    q.append((x, y))
        dist = [[INF]*m for _ in range(n)]
        dist[si][sj] = 0
        q = deque([(si, sj)])
        while q:
            i, j = q.popleft()
            if (i, j) == (di, dj):
                return dist[i][j]
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                x, y = i+dx, j+dy
                if 0 <= x < n and 0 <= y < m and land[x][y] != 'X' and dist[x][y] == INF and flood[x][y] > dist[i][j] + 1:
                    dist[x][y] = dist[i][j] + 1
                    q.append((x, y))
        return -1

