class Solution {
    public int minimumSeconds(char[][] land) {
        int n = land.length, m = land[0].length;
        int[][] flood = new int[n][m], dist = new int[n][m];
        for (int[] row : flood) Arrays.fill(row, Integer.MAX_VALUE);
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        Deque<int[]> q = new ArrayDeque<>();
        int si=0, sj=0, di=0, dj=0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                if (land[i][j] == '*') { flood[i][j] = 0; q.add(new int[]{i, j}); }
                else if (land[i][j] == 'S') { si = i; sj = j; }
                else if (land[i][j] == 'D') { di = i; dj = j; }
            }
        int[] dx = {1,-1,0,0}, dy = {0,0,1,-1};
        while (!q.isEmpty()) {
            int[] c = q.poll();
            for (int d = 0; d < 4; d++) {
                int x = c[0]+dx[d], y = c[1]+dy[d];
                if (x >= 0 && x < n && y >= 0 && y < m && land[x][y] == '.' && flood[x][y] == Integer.MAX_VALUE) {
                    flood[x][y] = flood[c[0]][c[1]] + 1;
                    q.add(new int[]{x, y});
                }
            }
        }
        dist[si][sj] = 0;
        Deque<int[]> pq = new ArrayDeque<>();
        pq.add(new int[]{si, sj});
        while (!pq.isEmpty()) {
            int[] c = pq.poll();
            if (c[0] == di && c[1] == dj) return dist[c[0]][c[1]];
            for (int d = 0; d < 4; d++) {
                int x = c[0]+dx[d], y = c[1]+dy[d];
                if (x >= 0 && x < n && y >= 0 && y < m && land[x][y] != 'X'
                    && dist[x][y] == Integer.MAX_VALUE && flood[x][y] > dist[c[0]][c[1]] + 1) {
                    dist[x][y] = dist[c[0]][c[1]] + 1;
                    pq.add(new int[]{x, y});
                }
            }
        }
        return -1;
    }
}

