        water, person = deque(), deque()
        visited = set()
        for i in range(n):
            for j in range(m):
                if land[i][j] == '*': water.append((i, j))
                elif land[i][j] == 'S': person.append((i, j)); visited.add((i, j))
                elif land[i][j] == 'D': goal = (i, j)
        t = 0
        while person:
            for _ in range(len(water)):
                i, j = water.popleft()
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    x, y = i+dx, j+dy
                    if 0 <= x < n and 0 <= y < m and land[x][y] == '.':
                        land[x][y] = '*'
                        water.append((x, y))
            for _ in range(len(person)):
                i, j = person.popleft()
                if (i, j) == goal: return t
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    x, y = i+dx, j+dy
                    if 0 <= x < n and 0 <= y < m and land[x][y] == '.' and (x, y) not in visited:
                        visited.add((x, y))
                        person.append((x, y))
            t += 1
        return -1

