                    if (x >= 0 && x < n && y >= 0 && y < m && land[x][y] == '.') {
                        land[x][y] = '*';
                        water.add(new int[]{x, y});
                    }
                }
            }
            int ps = person.size();
            while (ps-- > 0) {
                int[] c = person.poll();
                if (c[0] == gi && c[1] == gj) return t[0];
                for (int d = 0; d < 4; d++) {
